namespace UserAccess.Api.Domain.Entities;

public sealed class User
{
    private User()
    {
    }

    public User(string firstName, string lastName, string email, string passwordHash, string? imagePath = null)
    {
        Id = Guid.NewGuid();
        FirstName = firstName;
        LastName = lastName;
        Email = email;
        PasswordHash = passwordHash;
        ImagePath = imagePath;
        CreatedAtUtc = DateTime.UtcNow;
    }

    public Guid Id { get; private set; }
    public string FirstName { get; private set; } = string.Empty;
    public string LastName { get; private set; } = string.Empty;
    public string Email { get; private set; } = string.Empty;
    public string PasswordHash { get; private set; } = string.Empty;
    public string? ImagePath { get; private set; }
    public DateTime CreatedAtUtc { get; private set; }
}

using Microsoft.EntityFrameworkCore;
using UserAccess.Api.Domain.Entities;

namespace UserAccess.Api.Infrastructure.Persistence;

public sealed class UserDbContext(DbContextOptions<UserDbContext> options) : DbContext(options)
{
    public DbSet<User> Users => Set<User>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.ApplyConfiguration(new UserConfiguration());
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using UserAccess.Api.Domain.Entities;

namespace UserAccess.Api.Infrastructure.Persistence;

internal sealed class UserConfiguration : IEntityTypeConfiguration<User>
{
    public void Configure(EntityTypeBuilder<User> builder)
    {
        builder.ToTable("Users", table => table.HasCheckConstraint(
            "CK_Users_Email_Format",
            "length(\"Email\") BETWEEN 6 AND 254 " +
            "AND instr(\"Email\", '@') > 1 " +
            "AND length(\"Email\") - length(replace(\"Email\", '@', '')) = 1 " +
            "AND instr(substr(\"Email\", instr(\"Email\", '@') + 1), '.') > 1 " +
            "AND instr(\"Email\", ' ') = 0 " +
            "AND instr(\"Email\", '..') = 0 " +
            "AND \"Email\" = trim(\"Email\")"));

        builder.HasKey(user => user.Id);

        builder.Property(user => user.FirstName)
            .HasMaxLength(100)
            .IsRequired();

        builder.Property(user => user.LastName)
            .HasMaxLength(100)
            .IsRequired();

        builder.Property(user => user.Email)
            .HasMaxLength(254)
            .UseCollation("NOCASE")
            .IsRequired();

        builder.HasIndex(user => user.Email)
            .IsUnique()
            .HasDatabaseName("UX_Users_Email");

        builder.Property(user => user.PasswordHash)
            .HasMaxLength(512)
            .IsRequired();

        builder.Property(user => user.ImagePath)
            .HasMaxLength(2048);

        builder.Property(user => user.CreatedAtUtc)
            .IsRequired();
    }
}

using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

namespace UserAccess.Api.Infrastructure.Persistence;

public static class UserPersistenceRegistration
{
    public static IServiceCollection AddUserPersistence(
        this IServiceCollection services,
        IConfiguration configuration,
        IHostEnvironment environment)
    {
        var connectionString = configuration.GetConnectionString("DefaultConnection")
            ?? throw new InvalidOperationException("The user database connection string is not configured.");
        var sqliteConnection = new SqliteConnectionStringBuilder(connectionString);

        if (!string.Equals(sqliteConnection.DataSource, ":memory:", StringComparison.OrdinalIgnoreCase) &&
            !sqliteConnection.DataSource.StartsWith("file:", StringComparison.OrdinalIgnoreCase))
        {
            var databasePath = Path.GetFullPath(sqliteConnection.DataSource, environment.ContentRootPath);
            var databaseDirectory = Path.GetDirectoryName(databasePath);
            if (!string.IsNullOrEmpty(databaseDirectory))
            {
                Directory.CreateDirectory(databaseDirectory);
            }

            sqliteConnection.DataSource = databasePath;
        }

        services.AddDbContext<UserDbContext>(options => options.UseSqlite(sqliteConnection.ToString()));
        return services;
    }
}

using Microsoft.AspNetCore.Diagnostics;
using Shared.Contracts;
using UserAccess.Api.Infrastructure.Persistence;

namespace UserAccess.Api.Infrastructure;

public static class UserAccessApiBootstrap
{
    public static WebApplication BuildApplication(string[] args)
    {
        var builder = WebApplication.CreateBuilder(args);

        builder.Configuration.AddEnvironmentVariables();

        builder.Logging.ClearProviders();
        builder.Logging.AddConsole();
        builder.Logging.AddDebug();

        builder.Services.AddOpenApi();
        builder.Services.AddProblemDetails(options =>
        {
            options.CustomizeProblemDetails = context =>
            {
                context.ProblemDetails.Extensions["traceId"] = context.HttpContext.TraceIdentifier;
                context.ProblemDetails.Extensions["service"] = "UserAccess.Api";
            };
        });
        builder.Services.AddHealthChecks();
        builder.Services.AddEndpointsApiExplorer();
        builder.Services.AddUserPersistence(builder.Configuration, builder.Environment);

        var app = builder.Build();

        app.UseExceptionHandler(exceptionHandlerApp =>
        {
            exceptionHandlerApp.Run(async context =>
            {
                var exception = context.Features.Get<IExceptionHandlerFeature>()?.Error ??
                    new ApiException("An unexpected error occurred.", 500);

                var statusCode = exception is ApiException apiException
                    ? apiException.StatusCode
                    : 500;

                context.Response.StatusCode = statusCode;
                context.Response.ContentType = "application/json";

                var response = ErrorResponse.FromException(exception, statusCode, context.TraceIdentifier);
                await context.Response.WriteAsJsonAsync(response);
            });
        });

        app.UseStatusCodePages(async statusCodeContext =>
        {
            if (statusCodeContext.HttpContext.Response.HasStarted)
            {
                return;
            }

            statusCodeContext.HttpContext.Response.ContentType = "application/json";
            var statusCode = statusCodeContext.HttpContext.Response.StatusCode;
            await statusCodeContext.HttpContext.Response.WriteAsJsonAsync(
                new ErrorResponse("The request could not be processed.", statusCode, statusCodeContext.HttpContext.TraceIdentifier));
        });

        if (app.Environment.IsDevelopment())
        {
            app.MapOpenApi();
        }

        app.MapHealthChecks("/health");

        app.MapGet("/api/info", () => Results.Ok(ApiResponse<string>.Ok(
            "UserAccess.Api",
            "User access microservice for user registration and authentication.")));

        return app;
    }
}

